cd /home/japheth/Desktop/hauntview && node -e "
const fs = require('fs');
const path = require('path');
const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
const version = pkg.version || '0.0.0';
const now = new Date().toISOString();

// Collect steering files
const steeringDir = '.kiro/steering';
const steeringFiles = fs.existsSync(steeringDir)
  ? fs.readdirSync(steeringDir).filter(f => f.endsWith('.md'))
  : [];

// Collect hook files
const hooksDir = '.kiro/hooks';
const hookFiles = fs.existsSync(hooksDir)
  ? fs.readdirSync(hooksDir).filter(f => f.endsWith('.json'))
  : [];

// Collect spec dirs
const specsDir = '.kiro/specs';
const specDirs = fs.existsSync(specsDir)
  ? fs.readdirSync(specsDir, {withFileTypes: true})
      .filter(d => d.isDirectory())
      .map(d => d.name)
  : [];

const table = specDirs.map(s => {
  const files = fs.readdirSync(path.join(specsDir, s));
  return '| ' + s + ' | ' + files.join(', ') + ' |';
}).join('\n');

const content = [
  '# HauntView — Architecture Reference',
  '',
  '> Auto-generated by the Living Documentation Sync Hook. Do not edit by hand.',
  '> Last updated: ' + now + ' · v' + version,
  '',
  '## Specs',
  '',
  '| Spec | Files |',
  '|---|---|',
  table,
  '',
  '## Steering Files',
  '',
  steeringFiles.map(f => '- \`.kiro/steering/' + f + '\`').join('\n'),
  '',
  '## Hooks',
  '',
  hookFiles.map(f => '- \`.kiro/hooks/' + f + '\`').join('\n'),
  '',
  '## Quick Start',
  '',
  '\`\`\`bash',
  'pnpm install',
  'pnpm dev        # web UI at http://localhost:3000',
  'pnpm mcp        # MCP server (stdio)',
  'pnpm typecheck  # TypeScript check',
  'pnpm test       # unit + property tests',
  '\`\`\`',
].join('\n');

fs.writeFileSync('docs/ARCHITECTURE.md', content, 'utf8');
console.log('docs/ARCHITECTURE.md updated');
" 2>&1; exit 0
